editor='''using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public class EMFixedTravelObserver:MonoBehaviour{public int fps;public float step;public Type actorType;public bool emptyMiddle;private int emptyFrame;private List<string> rows=new List<string>();private string prior="";
 void Awake(){DontDestroyOnLoad(gameObject);Time.captureDeltaTime=1f/fps;Time.fixedDeltaTime=step;}
 void LateUpdate(){try{var actors=UnityEngine.Object.FindObjectsByType(actorType,FindObjectsInactive.Include,FindObjectsSortMode.None);if(actors.Length==0){if(emptyMiddle&&UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="FixedMiddle"){emptyFrame++;rows.Add("[1,"+emptyFrame+",0,0,0,0,1]");Time.captureDeltaTime=1f/fps;if(emptyFrame==5)UnityEngine.SceneManagement.SceneManager.LoadScene("FixedFinal");}return;}var actor=actors[0];var t=actorType;int stage=(int)t.GetField("Stage").GetValue(actor);int frame=(int)t.GetField("Frame").GetValue(actor);if(frame==0||prior==stage+":"+frame)return;prior=stage+":"+frame;var row=new List<string>{stage.ToString(),frame.ToString()};foreach(var name in new[]{"Starts","Fixeds","InitialFixed","Elapsed","StartedBeforeFixed"}){var value=t.GetField(name).GetValue(actor);row.Add(value is bool b?(b?"1":"0"):Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture));}rows.Add("["+string.Join(",",row)+"]");Time.captureDeltaTime=1f/fps;if(stage==2&&frame>=12){File.WriteAllText(Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_OUTPUT"),"{\\"status\\":\\"CAPTURED\\",\\"rows\\":["+string.Join(",",rows)+"]}");EditorApplication.Exit(0);}}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
public static class EMFixedTravelProbe{public static void Run(){try{bool restored=Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_RESTORED")=="1";bool emptyMiddle=Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_EMPTY")=="1";var type=typeof(TravelFixed).Assembly.GetType(restored?"RestoredTravelFixed":"TravelFixed");var sceneNames=new[]{"FixedStart","FixedMiddle","FixedFinal"};var paths=new List<EditorBuildSettingsScene>();for(int stage=0;stage<3;stage++){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);if(!emptyMiddle||stage!=1){var actor=new GameObject(sceneNames[stage]).AddComponent(type);type.GetField("Stage").SetValue(actor,stage);}var path="Assets/EngineMigratorFixedTravelProbe/Scenes/"+sceneNames[stage]+".unity";if(!EditorSceneManager.SaveScene(scene,path))throw new Exception("Private scene save failed");paths.Add(new EditorBuildSettingsScene(path,true));}EditorBuildSettings.scenes=paths.ToArray();EditorSceneManager.OpenScene(paths[0].path);var observer=new GameObject("Fixed travel observer").AddComponent<EMFixedTravelObserver>();observer.actorType=type;observer.emptyMiddle=emptyMiddle;observer.fps=int.Parse(Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_FPS"));observer.step=float.Parse(Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_STEP"),System.Globalization.CultureInfo.InvariantCulture);Time.captureDeltaTime=1f/observer.fps;Time.fixedDeltaTime=observer.step;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload|EnterPlayModeOptions.DisableSceneReload;var deadline=EditorApplication.timeSinceStartup+120;EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup>deadline)EditorApplication.Exit(2);};EditorApplication.EnterPlaymode();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}
'''
