code='''using EngineMigrator.Core;using System.Text.Json;
var home=HOME;var unity=UNITY;var core=CORE;string Hash(string p)=>Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(p)));
Dictionary<string,string> Files()=>Directory.GetFiles(Path.Combine(core,"Project/Source"),"*",SearchOption.AllDirectories).Concat(Directory.GetFiles(Path.Combine(core,"Project/Plugins/EMActorPort/Source"),"*",SearchOption.AllDirectories)).Where(p=>new[]{".h",".cpp",".cs"}.Contains(Path.GetExtension(p))).Concat(new[]{Path.Combine(core,"Project/Binaries/Win64/UnrealEditor-EMPortHost.dll"),Path.Combine(core,"Project/Plugins/EMActorPort/Binaries/Win64/UnrealEditor-EMActorPort.dll")}).ToDictionary(p=>p,Hash);
if(args.Length!=1)throw new ArgumentException("Explicit mode required");var descriptor=Path.Combine(core,"Project/RuntimeWorld.uproject");var manifest=Path.Combine(home,"build-hashes.json");
if(args[0]=="prepare"){foreach(var prior in ActorScripts.FromUnity(File.ReadAllText("tests/EngineMigrator.Checks/Fixtures/fixed-update.cs.txt")))File.WriteAllText(Path.Combine(core,"Project/Plugins/EMActorPort/Source/EMActorPort/Public",prior.Name),prior.Code);var files=ActorScripts.FromUnity(File.ReadAllText("tests/EngineMigrator.Checks/Fixtures/fixed-travel.cs.txt"));File.WriteAllText(Path.Combine(home,"TravelFixed.h"),files.Single().Code);File.WriteAllText(Path.Combine(core,"Project/Plugins/EMActorPort/Source/EMActorPort/Public/TravelFixed.h"),files.Single().Code);File.WriteAllText(Path.Combine(home,"restored.cs"),ActorScripts.ToUnity(files).Single().Code);File.WriteAllText(Path.Combine(core,"Project/Source/EMPortHost/EMPortHost.cpp"),File.ReadAllText("artifacts/ui-equality-check/core-host-before-ui-destruction.cpp.txt")+File.ReadAllText("tools/fixed-update-game-observer.cpp.txt")+File.ReadAllText("tools/fixed-travel-game-observer.cpp.txt"));return;}
if(args[0]=="build"){using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(10));await ResourcePorting.RunEditor(EngineLaunchSafety.Dotnet,[EngineLaunchSafety.Ubt,"RuntimeWorldEditor","Win64","Development","-Project="+descriptor,"-NoHotReload","-NoPCH","-NoSharedPCH","-log="+Path.Combine(home,"build.log")],core,timeout.Token);File.WriteAllText(manifest,JsonSerializer.Serialize(Files()));return;}
if(args[0].StartsWith("maps",StringComparison.Ordinal)){var mapParts=args[0].Split('-');float mapStep=mapParts.Length==3?int.Parse(mapParts[2])/1000f:.02f;var oldStep=Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_MAP_STEP");var oldEmpty=Environment.GetEnvironmentVariable("EM_FIXED_TRAVEL_MAP_EMPTY");Environment.SetEnvironmentVariable("EM_FIXED_TRAVEL_MAP_EMPTY",args[0].StartsWith("mapsempty",StringComparison.Ordinal)?"1":"0");Environment.SetEnvironmentVariable("EM_FIXED_TRAVEL_MAP_STEP",mapStep.ToString("R",System.Globalization.CultureInfo.InvariantCulture));try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unreal,[descriptor,"-run=pythonscript","-script="+MAPSCRIPT,"-nullrhi","-unattended","-nop4","-nosplash","-abslog="+Path.Combine(home,args[0]+".log")],core,timeout.Token);}finally{Environment.SetEnvironmentVariable("EM_FIXED_TRAVEL_MAP_STEP",oldStep);Environment.SetEnvironmentVariable("EM_FIXED_TRAVEL_MAP_EMPTY",oldEmpty);}return;}
var parts=args[0].Split('-');if(parts.Length!=3)throw new ArgumentException("mode-fps-stepMilliseconds required");string mode=parts[0];int fps=int.Parse(parts[1]);float step=int.Parse(parts[2])/1000f;var output=Path.Combine(home,args[0]+".json");var log=Path.Combine(home,args[0]+".log");if(File.Exists(output))throw new IOException("Fresh capture required");
if(mode is "original" or "restored" or "originalempty" or "restoredempty"){var settings=new[]{"EditorSettings.asset","TimeManager.asset","EditorBuildSettings.asset"}.Select(n=>Path.Combine(unity,"ProjectSettings",n)).ToArray();var before=settings.Select(File.ReadAllBytes).ToArray();var keys=new[]{"EM_FIXED_TRAVEL_OUTPUT","EM_FIXED_TRAVEL_RESTORED","EM_FIXED_TRAVEL_FPS","EM_FIXED_TRAVEL_STEP","EM_FIXED_TRAVEL_EMPTY"};var old=keys.Select(Environment.GetEnvironmentVariable).ToArray();var values=new[]{output,mode.StartsWith("restored",StringComparison.Ordinal)?"1":"0",fps.ToString(),step.ToString("R",System.Globalization.CultureInfo.InvariantCulture),mode.EndsWith("empty",StringComparison.Ordinal)?"1":"0"};for(int i=0;i<keys.Length;i++)Environment.SetEnvironmentVariable(keys[i],values[i]);try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180));await ResourcePorting.RunEditor(EngineLaunchSafety.Unity,["-batchmode","-nographics","-projectPath",unity,"-executeMethod","EMFixedTravelProbe.Run","-logFile",log],Directory.GetParent(unity)!.FullName,timeout.Token);if(!File.Exists(output))throw new IOException("Unity scene-travel capture missing");}finally{for(int i=0;i<settings.Length;i++)File.WriteAllBytes(settings[i],before[i]);for(int i=0;i<keys.Length;i++)Environment.SetEnvironmentVariable(keys[i],old[i]);}return;}
var built=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(manifest))!;var current=Files();if(built.Count!=current.Count||built.Any(p=>!current.TryGetValue(p.Key,out var hash)||hash!=p.Value))throw new IOException("Native source/binary build mismatch");using(var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(180))){if(mode is "native" or "nativeempty")await ResourcePorting.RunEditor(EngineLaunchSafety.Unreal,[descriptor,"/Game/FixedTravel/FixedStart","-game","-nullrhi","-RenderOffscreen","-nosound","-unattended","-nop4","-nosplash","-UseFixedTimeStep","-FPS="+fps,"-EMFixedTravelProbe="+output,mode=="nativeempty"?"-EMFixedTravelEmpty":"-EMFixedTravelStandard","-EMFixedStep="+step.ToString("R",System.Globalization.CultureInfo.InvariantCulture),"-abslog="+log],core,timeout.Token);else if(mode=="single")await ResourcePorting.RunEditor(EngineLaunchSafety.Unreal,[descriptor,"/Engine/Maps/Entry","-game","-nullrhi","-RenderOffscreen","-nosound","-unattended","-nop4","-nosplash","-UseFixedTimeStep","-FPS="+fps,"-EMFixedProbe="+output,"-EMFixedStep="+step.ToString("R",System.Globalization.CultureInfo.InvariantCulture),"-abslog="+log],core,timeout.Token);else throw new ArgumentException("Unknown mode");}if(!File.Exists(output))throw new IOException("Native scene capture missing");
'''
